flowchart TB
    %% ---------- Entidades ----------
    ORG["ORGANIZATION<br/>(Tenant raíz)"]
    USER["USER"]
    AGENT["AGENT"]
    TOOL["TOOL"]
    TACT["TOOL_ACTION"]
    POL["POLICY"]
    RULE["POLICY_RULE"]
    EXE["EXECUTION"]
    APR["APPROVAL"]
    ALR["ALERT"]
    AUD["AUDIT_EVENT"]
    KEY["API_KEY"]

    %% ---------- Relaciones de tenant ----------
    R1{"TIENE_USUARIO"}
    R2{"GOBIERNA"}
    R3{"REGISTRA"}
    R4{"DEFINE"}
    R5{"EMITE"}
    R6{"TRAZA"}
    R7{"RECIBE"}
    R8{"AUDITA"}
    ORG -- "(0,N)" --- R1 -- "(1,1)" --- USER
    ORG -- "(0,N)" --- R2 -- "(1,1)" --- AGENT
    ORG -- "(0,N)" --- R3 -- "(1,1)" --- TOOL
    ORG -- "(0,N)" --- R4 -- "(1,1)" --- POL
    ORG -- "(0,N)" --- R5 -- "(1,1)" --- KEY
    ORG -- "(0,N)" --- R6 -- "(1,1)" --- EXE
    ORG -- "(0,N)" --- R7 -- "(1,1)" --- ALR
    ORG -- "(0,N)" --- R8 -- "(1,1)" --- AUD

    %% ---------- Relaciones funcionales ----------
    R9{"PATROCINA"}
    R10{"AUTORIZADO_EN"}
    R11{"EXPONE"}
    R12{"CONTIENE"}
    R13{"REGULA"}
    R14{"APUNTA_A"}
    USER -- "(0,N)" --- R9 -- "(1,1)" --- AGENT
    AGENT -- "(0,N)" --- R10 -- "(0,N)" --- TOOL
    TOOL -- "(0,N)" --- R11 -- "(1,1)" --- TACT
    POL -- "(0,N)" --- R12 -- "(1,1)" --- RULE
    TACT -- "(0,N)" --- R13 -- "(1,1)" --- RULE
    AGENT -- "(0,N)" --- R14 -- "(0,1)" --- RULE

    %% ---------- Atributos de la relación asociativa ----------
    A1(["enabled"])
    A2(["config {JSONB}"])
    A3(["created_at"])
    R10 --- A1
    R10 --- A2
    R10 --- A3

    %% ---------- Ejecución y su ciclo HITL / alertas ----------
    R15{"EJECUTA"}
    R16{"DELEGA"}
    R17{"INVOCA_HERRAMIENTA"}
    R18{"INVOCA_ACCION"}
    R19{"DECIDE"}
    R20{"SUSPENDE"}
    R21{"RESUELVE_APROBACION"}
    R22{"ORIGINA"}
    R23{"RESUELVE_ALERTA"}
    AGENT -- "(0,N)" --- R15 -- "(1,1)" --- EXE
    USER -- "(0,N)" --- R16 -- "(0,1)" --- EXE
    TOOL -- "(0,N)" --- R17 -- "(1,1)" --- EXE
    TACT -- "(0,N)" --- R18 -- "(1,1)" --- EXE
    RULE -- "(0,N)" --- R19 -- "(0,1)" --- EXE
    EXE -- "(0,1)" --- R20 -- "(1,1)" --- APR
    USER -- "(0,N)" --- R21 -- "(0,1)" --- APR
    EXE -- "(0,N)" --- R22 -- "(0,1)" --- ALR
    USER -- "(0,N)" --- R23 -- "(0,1)" --- ALR

    %% ---------- Actor polimórfico de auditoría (conceptual, sin FK) ----------
    R24{"REALIZADO_POR<br/>(polimórfica)"}
    AUD -. "(1,1)" .- R24 -. "(0,N)" .- USER
    R24 -. "(0,N)" .- AGENT
    R24 -. "(0,N)" .- SYS(("SYSTEM"))

